-- PROTANNI synthetic analytical dataset
-- Fully synthetic. No production records were used.
DROP TABLE IF EXISTS subscription_revenue;
DROP TABLE IF EXISTS product_events;
DROP TABLE IF EXISTS acquisition_touches;
DROP TABLE IF EXISTS billing_subscriptions;
DROP TABLE IF EXISTS billing_plans;
DROP TABLE IF EXISTS routine_item_checkins;
DROP TABLE IF EXISTS routine_checkins;
DROP TABLE IF EXISTS routine_items;
DROP TABLE IF EXISTS routines;
DROP TABLE IF EXISTS tasks;
DROP TABLE IF EXISTS profiles;
DROP TABLE IF EXISTS users;

CREATE TABLE users (user_id VARCHAR PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL, is_anonymous BOOLEAN NOT NULL);
CREATE TABLE profiles (user_id VARCHAR PRIMARY KEY, locale VARCHAR, timezone VARCHAR, onboarding_completed BOOLEAN NOT NULL, is_paid BOOLEAN NOT NULL, daily_focus_updated_at TIMESTAMPTZ, ai_personalization_enabled BOOLEAN NOT NULL, market_key VARCHAR);
CREATE TABLE tasks (task_id VARCHAR PRIMARY KEY, user_id VARCHAR NOT NULL, created_at TIMESTAMPTZ NOT NULL, status VARCHAR NOT NULL, priority VARCHAR NOT NULL, due_date DATE, completed_at TIMESTAMPTZ, is_deleted BOOLEAN NOT NULL, area VARCHAR, is_today BOOLEAN NOT NULL, today_added_at TIMESTAMPTZ, parent_task_id VARCHAR);
CREATE TABLE routines (routine_id VARCHAR PRIMARY KEY, user_id VARCHAR NOT NULL, created_at TIMESTAMPTZ NOT NULL, period VARCHAR NOT NULL, is_active BOOLEAN NOT NULL, area VARCHAR, time_of_day VARCHAR, goal_duration INTEGER, start_date DATE);
CREATE TABLE routine_items (routine_item_id VARCHAR PRIMARY KEY, routine_id VARCHAR NOT NULL, user_id VARCHAR NOT NULL, created_at TIMESTAMPTZ NOT NULL, sort_order INTEGER NOT NULL, is_active BOOLEAN NOT NULL);
CREATE TABLE routine_checkins (routine_checkin_id VARCHAR PRIMARY KEY, user_id VARCHAR NOT NULL, routine_id VARCHAR NOT NULL, checkin_date DATE NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE routine_item_checkins (routine_item_checkin_id VARCHAR PRIMARY KEY, user_id VARCHAR NOT NULL, routine_checkin_id VARCHAR NOT NULL, routine_item_id VARCHAR NOT NULL, is_done BOOLEAN NOT NULL, done_at TIMESTAMPTZ);
CREATE TABLE billing_plans (plan_id VARCHAR PRIMARY KEY, plan_key VARCHAR NOT NULL, interval_unit VARCHAR NOT NULL, interval_count INTEGER NOT NULL, trial_days INTEGER NOT NULL, active BOOLEAN NOT NULL);
CREATE TABLE billing_subscriptions (subscription_id VARCHAR PRIMARY KEY, user_id VARCHAR NOT NULL, plan_id VARCHAR NOT NULL, provider VARCHAR NOT NULL, lifecycle_state VARCHAR NOT NULL, starts_at TIMESTAMPTZ, trial_starts_at TIMESTAMPTZ NOT NULL, trial_ends_at TIMESTAMPTZ NOT NULL, current_period_starts_at TIMESTAMPTZ, current_period_ends_at TIMESTAMPTZ, canceled_at TIMESTAMPTZ, auto_renews BOOLEAN NOT NULL);
CREATE TABLE acquisition_touches (acquisition_id VARCHAR PRIMARY KEY, user_id VARCHAR, occurred_at TIMESTAMPTZ NOT NULL, channel VARCHAR NOT NULL, source VARCHAR NOT NULL, medium VARCHAR NOT NULL, campaign VARCHAR NOT NULL, landing_page VARCHAR NOT NULL, market_key VARCHAR NOT NULL, is_qualified_visit BOOLEAN NOT NULL, converted_to_signup BOOLEAN NOT NULL);
CREATE TABLE product_events (event_id VARCHAR PRIMARY KEY, user_id VARCHAR NOT NULL, event_name VARCHAR NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, event_date DATE NOT NULL, surface VARCHAR NOT NULL, object_type VARCHAR, object_id VARCHAR, properties_json VARCHAR);
CREATE TABLE subscription_revenue (subscription_id VARCHAR NOT NULL, user_id VARCHAR NOT NULL, plan_id VARCHAR NOT NULL, month_start_date DATE NOT NULL, currency VARCHAR NOT NULL, gross_recurring_amount DECIMAL(10,2) NOT NULL, normalized_mrr DECIMAL(10,2) NOT NULL, is_new_mrr BOOLEAN NOT NULL, is_active_paid BOOLEAN NOT NULL);

